// Generated from src/registry/sources/control-ui/recipes/choice.css by scripts/gen-knob-contracts.ts — run `bun run sync:knobs`.
export const choiceKnobs = [
  "--cui-choice-radius",
  "--cui-choice-border-color",
  "--cui-choice-checked-background",
  "--cui-choice-checked-border-color",
] as const;
export type ChoiceKnobStyle = Partial<Record<(typeof choiceKnobs)[number], string>>;

@layer components {
  :where([data-control-family="choice"][data-choice-kind="checkbox"][data-slot="root"]),
  :where([data-control-family="choice"][data-choice-kind="radio-group"][data-slot="item"]) {
    inline-size: calc(var(--spacing) * 4);
    block-size: calc(var(--spacing) * 4);
    --cui-choice-radius: var(--radius-sm);
    --cui-choice-border-color: var(--border);
    --cui-choice-checked-background: var(--primary);
    --cui-choice-checked-border-color: var(--primary);
    --_choice-background: oklch(from var(--card) l c h / 0.72);
    border-radius: var(--cui-choice-radius);
    background: var(--_choice-background);
    box-shadow:
      inset 0 0 0 1px var(--cui-choice-border-color),
      var(--shadow-sm);
    color: currentColor;
    outline: none;
    transition-property: background-color, box-shadow, color;
    transition-duration: var(--duration-fast);
    transition-timing-function: var(--ease-standard);
  }

  :where([data-control-family="choice"][data-choice-kind="radio-group"][data-slot="item"]) {
    --cui-choice-radius: 9999px;
    outline-style: none;
  }

  :where([data-control-family="choice"][data-choice-kind="checkbox"][data-slot="root"]:hover),
  :where([data-control-family="choice"][data-choice-kind="radio-group"][data-slot="item"]:hover) {
    --cui-choice-border-color: oklch(from var(--foreground) l c h / 0.25);
  }

  :where([data-control-family="choice"][data-choice-kind="checkbox"][data-slot="root"]:is([data-checked], [data-indeterminate])),
  :where([data-control-family="choice"][data-choice-kind="radio-group"][data-slot="item"]:is([data-checked], [data-indeterminate])) {
    --_choice-background: var(--cui-choice-checked-background);
    --cui-choice-border-color: var(--cui-choice-checked-border-color);
    color: var(--primary-foreground);
  }

  :where([data-control-family="choice"][data-choice-kind="checkbox"][data-slot="root"][data-disabled]),
  :where([data-control-family="choice"][data-choice-kind="radio-group"][data-slot="item"][data-disabled]) {
    opacity: 0.5;
  }

  :where([data-control-family="choice"][data-choice-kind="checkbox"][data-slot="root"][data-invalid]),
  :where([data-control-family="choice"][data-choice-kind="radio-group"][data-slot="item"][data-invalid]) {
    --cui-choice-border-color: var(--destructive);
    box-shadow:
      inset 0 0 0 1px var(--cui-choice-border-color),
      var(--shadow-sm),
      0 0 0 1px var(--destructive);
  }

  :where([data-control-family="choice"][data-choice-kind="checkbox"][data-slot="root"] [data-slot="indicator"]),
  :where([data-control-family="choice"][data-choice-kind="radio-group"][data-slot="item"] [data-slot="indicator"]) {
    color: currentColor;
  }

  :where([data-control-family="choice"][data-choice-kind="radio-group"] [data-slot="indicator"]) {
    border-radius: 9999px;
    background: var(--primary-foreground);
  }

  :where([data-control-family="choice"][data-choice-kind="radio-group"][data-slot="root"]) {
    gap: calc(var(--spacing) * 2);
  }

  :where([data-control-family="choice"][data-choice-kind="radio-group"][data-slot="root"][data-orientation="horizontal"]) {
    gap: calc(var(--spacing) * 4);
  }

  :where([data-control-family="choice"][data-choice-kind="radio-group"][data-slot="indicator"]) {
    inline-size: calc(var(--spacing) * 1.5);
    block-size: calc(var(--spacing) * 1.5);
  }

  :where([data-control-family="choice"][data-choice-kind="checkbox"][data-slot="indicator"]) {
    color: currentcolor;
  }

  :where([data-control-family="choice"][data-choice-kind="checkbox"][data-slot="root"]) {
    outline-style: none;
  }
}

@property --cui-choice-radius {
  syntax: "<length-percentage>";
  inherits: true;
  initial-value: 0px;
}

@property --cui-choice-border-color {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --cui-choice-checked-background {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --cui-choice-checked-border-color {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

"use client";

import { Radio as RadioPrimitive } from "@base-ui/react/radio";
import { RadioGroup as RadioGroupPrimitive } from "@base-ui/react/radio-group";
import type { ComponentProps, CSSProperties } from "react";
import type { ControlledChoice } from "@/components/control-ui/control-props";
import type { ChoiceKnobStyle } from "@/components/control-ui/knob-contracts/choice-knobs";
import { cn } from "@/components/control-ui/lib/cn";

export type RadioGroupProps<TValue extends string = string> = Omit<ComponentProps<"div">, "defaultValue" | "onChange"> &
  ControlledChoice<TValue> & {
    disabled?: boolean;
    readOnly?: boolean;
    required?: boolean;
    name?: string;
    orientation?: "horizontal" | "vertical";
  } & { style?: CSSProperties & ChoiceKnobStyle };

export type RadioProps = Omit<
  {
    value: string;
    disabled?: boolean;
    readOnly?: boolean;
    required?: boolean;
    id?: string;
    className?: string;
    "aria-label"?: string;
    "aria-labelledby"?: string;
  },
  "style"
> & { style?: CSSProperties & ChoiceKnobStyle };

// `orientation` is visual only — Base UI owns roving focus on both axes and exposes no such prop.
export function RadioGroup<TValue extends string = string>({ className, orientation = "vertical", ...props }: RadioGroupProps<TValue>) {
  return (
    <RadioGroupPrimitive<TValue>
      data-control-ui="radio-group"
      data-control-family="choice"
      data-choice-kind="radio-group"
      data-slot="root"
      data-orientation={orientation}
      className={cn("flex data-[orientation=horizontal]:flex-row data-[orientation=vertical]:flex-col", className)}
      {...props}
    />
  );
}

export function Radio({ className, disabled, ...props }: RadioProps) {
  return (
    <RadioPrimitive.Root
      data-control-ui="radio-group"
      data-choice-kind="radio-group"
      data-slot="item"
      data-control-family="choice"
      disabled={disabled}
      className={cn(
        "group/radio relative inline-flex shrink-0 cursor-pointer items-center justify-center",
        "data-[disabled]:cursor-not-allowed",
        className,
      )}
      {...props}
    >
      <RadioPrimitive.Indicator
        data-control-ui="radio-group"
        data-control-family="choice"
        data-choice-kind="radio-group"
        data-slot="indicator"
        className="data-[unchecked]:hidden"
      />
    </RadioPrimitive.Root>
  );
}
